pub struct ListCommand;

/// Serialize a slice of TimeEntry references as a JSON array,
/// injecting a `"running"` boolean into each entry.
fn time_entries_to_json(entries: &[&TimeEntry]) -> String {
    let values: Vec<serde_json::Value> = entries
        .iter()
        .map(|entry| {
            let mut value = serde_json::to_value(entry).expect("failed to serialize time entry");
            if entry.is_running() {
                if let Some(obj) = value.as_object_mut() {
                    obj.insert("running".to_string(), serde_json::Value::Bool(true));
                }
            }
            value
        })
        .collect();
    serde_json::to_string(&values).expect("failed to serialize time entries to JSON")
}

fn write_entries_grouped_by_date(handle: &mut impl Write, entries: &[&TimeEntry]) {
    let mut current_date: Option<chrono::NaiveDate> = None;
    for entry in entries {
        let local_start: DateTime<Local> = entry.start.with_timezone(&Local);
        let date = local_start.date_naive();
        if current_date != Some(date) {
            if current_date.is_some() {
                writeln!(handle).expect("failed to print");
            }
            writeln!(handle, "── {} ──", date.format("%Y-%m-%d %A")).expect("failed to print");
            current_date = Some(date);
        }
        writeln!(handle, "{entry}").expect("failed to print");
    }
}

impl ListCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        count: Option<usize>,
        json_flag: bool,
        since: Option<String>,
        until: Option<String>,
        entity: Option<Entity>,
    ) -> ResultWithDefaultError<()> {
        let is_time_entry = matches!(entity, None | Some(Entity::TimeEntry { .. }));
        let has_date_filter = since.is_some() || until.is_some();

        if is_time_entry && has_date_filter {
            let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
            let stdout = io::stdout();
            let mut handle = BufWriter::new(stdout);
            let json = match &entity {
                Some(Entity::TimeEntry { json }) => json_flag || *json,
                _ => json_flag,
            };
            let entries = if json {
                api_client
                    .get_time_entries_filtered_minimal(since, until)
                    .await
            } else {
                api_client.get_time_entries_filtered(since, until).await
            };
            match entries {
                Err(error) => {
                    return Err(error);
                }
                Ok(mut entries) => {
                    entries.sort_by_key(|e| e.start);
                    let entries = entries
                        .iter()
                        .take(count.unwrap_or(usize::MAX))
                        .collect::<Vec<_>>();
                    if json {
                        let json_string = time_entries_to_json(&entries);
                        writeln!(handle, "{json_string}").expect("failed to print");
                    } else if entries.is_empty() {
                        eprintln!("No entries found.");
                    } else {
                        write_entries_grouped_by_date(&mut handle, &entries);
                    }
                }
            }
            return Ok(());
        }

        if let Some(Entity::Tag { json: entity_json }) = entity {
            let json = json_flag || entity_json;
            let user = api_client.get_user().await?;
            match api_client.get_tags(user.default_workspace_id).await {
                Err(error) => {
                    return Err(error);
                }
                Ok(tags) => {
                    let stdout = io::stdout();
                    let mut handle = BufWriter::new(stdout);
                    let tags = tags
                        .iter()
                        .take(count.unwrap_or(usize::MAX))
                        .collect::<Vec<_>>();
                    if json {
                        let json_string =
                            serde_json::to_string(&tags).expect("failed to serialize tags to JSON");
                        writeln!(handle, "{json_string}").expect("failed to print");
                    } else {
                        tags.iter()
                            .for_each(|tag| writeln!(handle, "{tag}").expect("failed to print"));
                    }
                }
            }
            return Ok(());
    async fn stop_time_entry(
        &self,
        workspace_id: i64,
        time_entry_id: i64,
    ) -> ResultWithDefaultError<TimeEntry> {
        let url = format!(
            "{}/workspaces/{}/time_entries/{}/stop",
            self.base_url, workspace_id, time_entry_id
        );
        let network_entry = self.patch_without_body::<NetworkTimeEntry>(url).await?;
        Ok(self.hydrate_single_network_entry(network_entry).await)
    }

    async fn bulk_update_time_entries(
        &self,
        workspace_id: i64,
        time_entry_ids: Vec<i64>,
        patch: Value,
    ) -> ResultWithDefaultError<Value> {
        let ids = time_entry_ids
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join(",");
        let url = format!(
            "{}/workspaces/{}/time_entries/{}",
            self.base_url, workspace_id, ids
        );
        self.patch::<Value, Value>(url, &patch).await
    }

    async fn get_time_entries_filtered(
        &self,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<Vec<TimeEntry>> {
        let (network_entries, network_projects, network_tasks, network_clients) = tokio::join!(
            self.get_time_entries(since.as_deref(), until.as_deref()),
            self.get_projects(),
            self.get_tasks(),
            self.get_clients(),
        );

        let clients: HashMap<i64, crate::models::Client> = network_clients
            .unwrap_or_default()
            .into_iter()
            .map(|c| {
                (
                    c.id,
                    crate::models::Client {
                        id: c.id,
                        name: c.name,
                        workspace_id: c.wid,
                        archived: c.archived,
                    },
                )
            })
            .collect();

        let projects: HashMap<i64, Project> = network_projects
            .unwrap_or_default()
            .into_iter()
            .map(|p| {
                (
                    p.id,
                    Project {
                        id: p.id,
                        name: p.name.clone(),
                        workspace_id: p.workspace_id,
                        client: clients.get(&p.client_id.unwrap_or(-1)).cloned(),
                        is_private: p.is_private,
                        active: p.active,
                        at: p.at,
                        created_at: p.created_at,
                        color: p.color,
                        billable: p.billable,
                    },
                )
            })
            .collect();

        let tasks: HashMap<i64, Task> = network_tasks
            .unwrap_or_default()
            .into_iter()
            .filter_map(|t| {
                projects.get(&t.project_id).map(|project| {
                    (
                        t.id,
                        Task {
                            id: t.id,
                            name: t.name,
                            project: project.clone(),
                            workspace_id: t.workspace_id,
                            active: t.active.unwrap_or(true),
                        },
                    )
                })
            })
            .collect();

        let entries = network_entries?
            .into_iter()
            .map(|te| TimeEntry {
                id: te.id,
                description: te.description,
                start: te.start,
                stop: te.stop,
                duration: te.duration,
                billable: te.billable,
                workspace_id: te.workspace_id,
                tags: te.tags.unwrap_or_default(),
                project: projects.get(&te.project_id.unwrap_or(-1)).cloned(),
                task: tasks.get(&te.task_id.unwrap_or(-1)).cloned(),
                ..Default::default()
            })
            .collect();

        Ok(entries)
    }

    async fn get_time_entries_filtered_minimal(
        &self,
        since: Option<String>,
        until: Option<String>,
